package com.vandorlabs.neoforge.propulsion;
import com.vandorlabs.propulsion.PropulsionDefinition;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.inventory.MenuType;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.phys.Vec3;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
/** Private real hosts and source-owning thread assertions; no public propulsion IDs or bootstrap hook. */
@EventBusSubscriber(modid="vandorlabs")
public final class PropulsionWorldFixture {
 public static final BlockPos BASE=new BlockPos(0,80,0),EDITOR=BASE.east(5);
 public static final Map<String,NativePropulsionBlock> BLOCKS=new LinkedHashMap<>();public static BlockEntityType<NativePropulsionEntity> TYPE;public static MenuType<NativePropulsionMenu> MENU;private static boolean complete;private static int lightTicks=-1;
 public static boolean canonical(){return "true".equals(System.getenv("VANDOR_PROPULSION_CANONICAL_CHECK"));}
 public static void bindCanonical(){if(!canonical())return;BLOCKS.clear();for(var d:PropulsionDefinition.values())BLOCKS.put(d.id,(NativePropulsionBlock)net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(ResourceLocation.parse("vandorlabs:"+d.id)));TYPE=NativePropulsionRegistrations.ENTITY.get();MENU=NativePropulsionRegistrations.MENU.get();}
 public static boolean enabled(){return "propulsion-world-client".equals(System.getProperty("vandorlabs.transmitterPhase"));}
 private static void need(boolean yes,String text){if(!yes)throw new AssertionError("Propulsion world server: "+text);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {
  @SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled()||canonical())return;event.register(Registries.BLOCK,h->{for(var definition:PropulsionDefinition.values()){var block=new NativePropulsionBlock(definition.id,BlockBehaviour.Properties.of().strength(5,10),()->TYPE,BLOCKS::get){@Override protected MenuType<NativePropulsionMenu> menuType(){return MENU;}};BLOCKS.put(definition.id,block);h.register(ResourceLocation.parse("vandorlabs:propulsion_world_fixture_"+definition.id),block);}});event.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.of((p,s)->new NativePropulsionEntity(TYPE,p,s),BLOCKS.values().toArray(NativePropulsionBlock[]::new)).build(null);h.register(ResourceLocation.parse("vandorlabs:propulsion_world_fixture"),TYPE);});event.register(Registries.MENU,h->{MENU=net.neoforged.neoforge.common.extensions.IMenuTypeExtension.create((id,inventory,buf)->{if(buf.readableBytes()!=8)throw new IllegalArgumentException("Fixture menu target length");return new NativePropulsionMenu(MENU,id,inventory,buf.readBlockPos());});h.register(ResourceLocation.parse("vandorlabs:propulsion_world_fixture"),MENU);});}
  @SubscribeEvent public static void payload(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent event){if(!enabled())return;if(!net.minecraft.core.registries.BuiltInRegistries.BLOCK.containsKey(ResourceLocation.parse("vandorlabs:rocket_thruster")))PropulsionSettingsPayload.register(event);event.registrar("1").playToServer(Mode.TYPE,new StreamCodec<RegistryFriendlyByteBuf,Mode>(){public Mode decode(RegistryFriendlyByteBuf b){if(b.readableBytes()!=1)throw new IllegalArgumentException("Fixture mode size");return new Mode(b.readUnsignedByte());}public void encode(RegistryFriendlyByteBuf b,Mode m){b.writeByte(m.operation());}},(p,c)->c.enqueueWork(()->{if(c.player() instanceof ServerPlayer player)mode(player,p.operation());}));}
 }
 public record Mode(int operation) implements CustomPacketPayload {public static final Type<Mode> TYPE=new Type<>(ResourceLocation.parse("vandorlabs:propulsion_world_mode"));public Type<? extends CustomPacketPayload> type(){return TYPE;}}
 private static NativePropulsionEntity at(ServerLevel world,BlockPos pos){return (NativePropulsionEntity)world.getBlockEntity(pos);}
 private static void pose(ServerPlayer player,int kind){boolean wide=kind==0;player.setGameMode(kind==1?GameType.SURVIVAL:GameType.CREATIVE);player.getInventory().clearContent();player.getInventory().selected=0;player.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);if(kind==2)player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(com.vandorlabs.neoforge.VandorLabsBootstrap.CONFIGURIZER.get()));player.getAbilities().flying=wide;player.onUpdateAbilities();double x=wide?10.5:kind==2?5.5:1.5,y=wide?81:80,z=wide?-17:-3;Vec3 target=new Vec3(x,wide?81.3:80.5,0);double dx=target.x-x,dz=target.z-z,dy=target.y-y-player.getEyeHeight();player.connection.teleport(x,y,z,(float)-Math.toDegrees(Math.atan2(dx,dz)),(float)-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz))));player.inventoryMenu.broadcastChanges();}
 private static void put(ServerLevel world,BlockPos pos,String id){var state=BLOCKS.get(id).defaultBlockState().setValue(NativePropulsionBlock.FACING,Direction.NORTH);world.setBlock(pos,state,18);var tag=new CompoundTag();tag.putBoolean("ManualOn",true);tag.putBoolean("LightInitialized",true);tag.putBoolean("PropulsionJoin",true);tag.putInt("ParticleLevel",0);tag.putInt("PropulsionSideTexture",9);tag.putString("PrivatePropulsionMarker","server-only");at(world,pos).loadWithComponents(tag,world.registryAccess());}
 @SubscribeEvent public static void started(net.neoforged.neoforge.event.server.ServerStartedEvent event){if(enabled()){gallery(event.getServer().overworld());System.out.println("[vandorlabs][propulsion-world] actual server PID="+ProcessHandle.current().pid());}}
 private static void gallery(ServerLevel world){bindCanonical();var w=world;w.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DOMOBSPAWNING).set(false,w.getServer());w.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DAYLIGHT).set(false,w.getServer());w.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_WEATHER_CYCLE).set(false,w.getServer());w.setDayTime(18000);w.setWeatherParameters(0,6000,false,false);for(int x=-5;x<=26;x++)for(int z=-22;z<=5;z++){w.setBlock(new BlockPos(x,79,z),Blocks.STONE.defaultBlockState(),18);for(int y=80;y<=84;y++)w.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),18);}for(int x=0;x<3;x++)for(int y=0;y<3;y++)put(w,BASE.offset(x,y,0),"rocket_thruster");String[] ids={"ion_drive","plasma_vent","impulse_engine","antigravity_plate","repulsor_array","vertical_hover_thruster"};for(int i=0;i<ids.length;i++)put(w,BASE.east(5+i*2),ids[i]);for(int x=0;x<2;x++)for(int y=0;y<2;y++)put(w,BASE.offset(18+x,y,0),"rocket_thruster_hexagonal");put(w,BASE.east(21),"ion_drive_wedge_top_left");NativePropulsionService.flush(w);int[] lights={0};w.getChunkAt(BASE).findBlockLightSources((pos,state)->{if(state.getBlock() instanceof NativePropulsionBlock)lights[0]++;});need(lights[0]==15,"actual chunk source discovery includes all first-chunk engine positions: "+lights[0]);lightTicks=0;System.out.println("[vandorlabs][propulsion-world] setup PASS actual20hosts/7families/3x3square/2x2hex/wedge/chunkLightSources="+lights[0]);}
 @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent event){if(enabled()&&event.getEntity() instanceof ServerPlayer p)pose(p,0);}
 private static void mode(ServerPlayer p,int operation){var w=p.serverLevel();switch(operation){case 0->pose(p,1);case 1->{for(int x=0;x<3;x++)for(int y=0;y<3;y++)need(at(w,BASE.offset(x,y,0)).settings().data().manualMode()==2,"actual survival use sets complete nine-member Stream");pose(p,0);System.out.println("[vandorlabs][propulsion-world] stream PASS actual vanilla survival packet all9");}case 2->pose(p,2);case 3->{need(at(w,EDITOR).settings().data().sideTexture==64&&at(w,EDITOR).settings().data().particleLevel==3,"real dedicated menu/payload installs complete draft");pose(p,0);System.out.println("[vandorlabs][propulsion-world] editor PASS real dedicated menu/server choices");}case 4->{complete=true;System.out.println("[vandorlabs][propulsion-world] complete PASS");}default->throw new IllegalArgumentException("Unknown fixture operation");}}
 @SubscribeEvent public static void light(net.neoforged.neoforge.event.tick.LevelTickEvent.Post event){if(enabled()&&lightTicks>=0&&event.getLevel() instanceof ServerLevel world&&world.dimension()==net.minecraft.world.level.Level.OVERWORLD){int t=++lightTicks;if(t==100){need(world.getBrightness(net.minecraft.world.level.LightLayer.BLOCK,BASE.above(3))==14,"settled pre-login gallery air14");System.out.println("[vandorlabs][propulsion-world] settled gallery READY");}if(t==20||t==100||t==300)System.out.println("[vandorlabs][propulsion-world] physical light tick="+t+" source="+world.getBrightness(net.minecraft.world.level.LightLayer.BLOCK,BASE.above(2))+" air="+world.getBrightness(net.minecraft.world.level.LightLayer.BLOCK,BASE.above(3))+" north="+world.getBrightness(net.minecraft.world.level.LightLayer.BLOCK,BASE.north())+" aux="+world.getAuxLightManager(BASE).getLightAt(BASE)+" opacity="+world.getBlockState(BASE).getLightBlock(world,BASE));}}
 @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent event){if(enabled()){System.out.println("[vandorlabs][propulsion-world] logout "+(complete?"PASS":"INCOMPLETE"));if(complete&&event.getEntity() instanceof ServerPlayer player)player.getServer().halt(false);}}
}
